//! The render pipeline.
//!
//! text --markup--> spans --(group by persona, split sentences)--> sentences of runs
//!
//! Expressive personas (Chatterbox): every run is generated by the emotional model with
//! its own emotion intensity ("exaggeration") and a mood-shaped voice prompt, then
//! stitched. Post-processing is kept minimal (explicit pitch/rate, level, room) for clarity.
//!
//! Lite personas (Kokoro / Piper): one neural pass per sentence, run boundaries estimated,
//! moods rendered by DSP (PSOLA intonation, LPC whisper, tilt, tremolo, room).

use crate::backend::{Kokoro, ModelControls, Piper, SynthOut};
use crate::chatterbox::{self, CbParams, Chatterbox, VoiceCond};
use crate::dsp::effects;
use crate::dsp::pitch::{map_time, pitch_marks, psola, yin};
use crate::export::Cue;
use crate::markup::{Item, Parser, Span};
use crate::mood::{builtin_moods, Mood};
use crate::persona::{builtin_personas, Accent, Persona, VoiceRef};
use crate::phonemize::Phonemizer;
use crate::util::{db_to_lin, suggest, Rng};
use anyhow::{anyhow, bail, Context, Result};
use serde::Deserialize;
use std::collections::HashMap;
use std::path::{Path, PathBuf};

#[derive(Clone, Debug)]
pub struct RenderOptions {
    pub persona: String,
    /// Mood mix applied where the text doesn't specify one (empty = persona default).
    pub moods: Vec<(String, f32)>,
    pub rate: f32,
    pub pitch_st: f32,
    pub volume_db: f32,
    pub sample_rate: u32,
    pub sentence_pause_ms: f32,
    pub normalize: bool,
    pub target_db: f32,
    pub seed: u64,
    /// Treat the whole input as IPA phonemes (lite personas only).
    pub ipa: bool,
    /// Override emotion intensity for expressive personas (0.25..2).
    pub emotion: Option<f32>,
    /// Clone this WAV voice instead of the persona's reference (expressive personas).
    pub clone: Option<PathBuf>,
}

impl Default for RenderOptions {
    fn default() -> Self {
        RenderOptions {
            persona: "emma".into(),
            moods: vec![],
            rate: 1.0,
            pitch_st: 0.0,
            volume_db: 0.0,
            sample_rate: 24_000,
            sentence_pause_ms: 380.0,
            normalize: true,
            target_db: -18.0,
            seed: 7,
            ipa: false,
            emotion: None,
            clone: None,
        }
    }
}

#[derive(Default, Deserialize)]
pub struct UserConfig {
    #[serde(default)]
    pub persona: Vec<Persona>,
    #[serde(default)]
    pub mood: Vec<Mood>,
}

impl UserConfig {
    pub fn load(path: &Path) -> Result<Self> {
        let s = std::fs::read_to_string(path).with_context(|| format!("reading {}", path.display()))?;
        toml::from_str(&s).with_context(|| format!("parsing {}", path.display()))
    }
}

pub struct Rendered {
    pub samples: Vec<f32>,
    pub sample_rate: u32,
    /// One cue per styled run (word groups sharing persona+mood).
    pub runs: Vec<Cue>,
    /// One cue per sentence (for subtitles).
    pub sentences: Vec<Cue>,
}

/// Adjustments that are not part of the mood (persona base, CLI, <prosody>, emphasis).
#[derive(Clone, Copy, Debug)]
struct Explicit {
    rate: f32,
    pitch_st: f32,
    gain_db: f32,
    emphasis: bool,
}

#[derive(Clone)]
struct Run {
    text: String,
    ipa: bool,
    /// Fully resolved style (lite engines).
    style: Mood,
    /// Mood mix only (expressive engine).
    mood: Mood,
    explicit: Explicit,
    label: String,
    nonverbal: Option<String>,
    /// Strongest mood of the mix (drives the emotional voice prompt).
    dominant: Option<(String, f32)>,
}

enum Piece {
    Utt { persona: String, runs: Vec<Run> },
    Pause(f32),
    Breath,
}

struct SentenceAudio {
    audio: Vec<f32>,
    /// run start positions in output samples (len = runs+1)
    bounds: Vec<usize>,
    ended: bool,
    pause_scale: f32,
}

pub struct Engine {
    pub models_dir: PathBuf,
    personas: Vec<Persona>,
    moods: Vec<Mood>,
    phon: Option<Phonemizer>,
    kokoro: Option<Kokoro>,
    piper: HashMap<String, Piper>,
    cb: Option<Chatterbox>,
    cb_refs: HashMap<String, Vec<f32>>,
    cb_conds: HashMap<String, VoiceCond>,
    pub verbose: bool,
}

const REF_TEXT_EN: &str = "It was a quiet morning in the city, and the sun was just beginning to rise above the rooftops. I poured myself a cup of coffee and watched the streets slowly come to life.";
const REF_IPA_EN: &str = "ɪt wʌz ɐ kwˈaɪət mˈɔːɹnɪŋ ɪnðə sˈɪɾi, ænd ðə sˈʌn wʌz dʒˈʌst bɪɡˈɪnɪŋ tə ɹˈaɪz əbˌʌv ðə ɹˈuːftɑːps. aɪ pˈoːɹd maɪsˈɛlf ɐ kˈʌp ʌv kˈɔfi ænd wˈɑːtʃt ðə stɹˈiːts slˈoʊli kˈʌm tə lˈaɪf.";
const REF_TEXT_FR: &str = "Ce matin, le soleil se levait doucement sur la ville. J'ai pris un café en terrasse, et j'ai regardé les passants flâner dans les rues encore calmes.";
const REF_IPA_FR: &str = "sə matˈɛ̃, lə sɔlˈɛj sə ləvˈɛ dusmˈɑ̃ syʁ la vˈil. ʒe pʁˈi œ̃ kafˈe ɑ̃ teʁˈas, e ʒe ʁəɡaʁdˈe le pasˈɑ̃ flɑnˈe dɑ̃ le ʁˈy ɑ̃kˈɔʁ kˈalm.";

impl Engine {
    pub fn new(models_dir: PathBuf, user: Option<UserConfig>) -> Self {
        let mut personas = builtin_personas();
        let mut moods = builtin_moods();
        if let Some(u) = user {
            for mut p in u.persona {
                p.name = p.name.to_ascii_lowercase();
                personas.retain(|x| x.name != p.name);
                personas.push(p);
            }
            for mut m in u.mood {
                m.name = m.name.to_ascii_lowercase();
                moods.retain(|x| x.name != m.name);
                moods.push(m);
            }
        }
        Engine {
            models_dir,
            personas,
            moods,
            phon: None,
            kokoro: None,
            piper: HashMap::new(),
            cb: None,
            cb_refs: HashMap::new(),
            cb_conds: HashMap::new(),
            verbose: false,
        }
    }

    pub fn personas(&self) -> &[Persona] {
        &self.personas
    }
    pub fn moods(&self) -> &[Mood] {
        &self.moods
    }

    pub fn persona(&self, name: &str) -> Result<&Persona> {
        let n = name.to_ascii_lowercase();
        self.personas.iter().find(|p| p.name == n).ok_or_else(|| {
            anyhow!("unknown persona '{name}'{}", suggest(&n, self.personas.iter().map(|p| p.name.as_str())))
        })
    }

    pub fn mood(&self, name: &str) -> Result<&Mood> {
        let n = name.to_ascii_lowercase();
        self.moods
            .iter()
            .find(|m| m.name == n)
            .ok_or_else(|| anyhow!("unknown mood '{name}'{}", suggest(&n, self.moods.iter().map(|m| m.name.as_str()))))
    }

    /// Whether the model files for a persona are present.
    pub fn available(&self, p: &Persona) -> bool {
        match &p.voice {
            VoiceRef::Kokoro { voices } => {
                let d = self.models_dir.join("kokoro");
                d.join("model.onnx").exists() && voices.iter().all(|v| Kokoro::has_voice(&d, &v.id))
            }
            VoiceRef::Piper { model, .. } => self.models_dir.join("piper").join(format!("{model}.onnx")).exists(),
            VoiceRef::Chatterbox { reference } => {
                let d = chatterbox::default_dir(&self.models_dir);
                Chatterbox::available(&d)
                    && match reference.as_str() {
                        "default" => d.join("default_voice.wav").exists(),
                        r if r.starts_with("persona:") => {
                            let src = &r["persona:".len()..];
                            d.join("voices").join(format!("{src}.wav")).exists()
                                || self.persona(src).map(|sp| self.available(sp)).unwrap_or(false)
                        }
                        path => Path::new(path).exists(),
                    }
            }
        }
    }

    fn phonemizer(&mut self) -> Result<&Phonemizer> {
        if self.phon.is_none() {
            self.phon = Some(Phonemizer::new()?);
        }
        Ok(self.phon.as_ref().unwrap())
    }

    fn mix(&self, moods: &[(String, f32)]) -> Result<Mood> {
        let parts: Vec<(&Mood, f32)> = moods.iter().map(|(n, k)| self.mood(n).map(|m| (m, *k))).collect::<Result<_>>()?;
        Ok(Mood::mix(&parts))
    }

    #[allow(clippy::type_complexity)]
    fn resolve_style(
        &self,
        span: &Span,
        persona: &Persona,
        opt: &RenderOptions,
    ) -> Result<(Mood, Mood, Explicit, String, Option<(String, f32)>)> {
        let list: Vec<(String, f32)> = if !span.moods.is_empty() {
            span.moods.clone()
        } else if !opt.moods.is_empty() {
            opt.moods.clone()
        } else {
            vec![(persona.mood.clone(), 1.0)]
        };
        let base = self.mix(&list)?;
        let dominant = list.iter().cloned().max_by(|a, b| a.1.partial_cmp(&b.1).unwrap());
        let mut label = base.name.clone();
        let ex = Explicit {
            rate: persona.speed * opt.rate * span.rate,
            pitch_st: persona.pitch_st + opt.pitch_st + span.pitch_st,
            gain_db: opt.volume_db + span.volume_db,
            emphasis: span.emphasis,
        };
        let mut m = base.clone();
        m.speed *= ex.rate;
        m.pitch_st += ex.pitch_st;
        m.gain_db += ex.gain_db;
        if span.emphasis {
            m.gain_db += 3.0;
            m.pitch_st += 1.5;
            m.pitch_range *= 1.3;
            m.speed *= 0.9;
            m.brightness_db += 1.5;
            label += "+emphasis";
        }
        Ok((m, base, ex, label, dominant))
    }

    pub fn render(&mut self, text: &str, opt: &RenderOptions) -> Result<Rendered> {
        self.persona(&opt.persona)?;
        for (m, _) in &opt.moods {
            self.mood(m)?;
        }
        let mood_names: Vec<String> = self.moods.iter().map(|m| m.name.clone()).collect();
        let is_mood = |n: &str| mood_names.iter().any(|m| m == n);
        let mut items = Parser::new(&is_mood).parse(text)?;
        if opt.ipa {
            for it in items.iter_mut() {
                if let Item::Speech(s) = it {
                    s.ipa = true;
                }
            }
        }

        // ---- group into pieces
        let mut pieces: Vec<Piece> = Vec::new();
        for it in items {
            match it {
                Item::Pause { ms } => pieces.push(Piece::Pause(ms)),
                Item::Breath => pieces.push(Piece::Breath),
                Item::Speech(span) => {
                    let pname = span.persona.clone().unwrap_or_else(|| opt.persona.clone()).to_ascii_lowercase();
                    let persona = self.persona(&pname)?.clone();
                    let (style, mood, explicit, label, dominant) = self.resolve_style(&span, &persona, opt)?;
                    let text = span.text.split_whitespace().collect::<Vec<_>>().join(" ");
                    if text.is_empty() {
                        continue;
                    }
                    let run =
                        Run { text, ipa: span.ipa, style, mood, explicit, label, nonverbal: span.nonverbal.clone(), dominant };
                    match pieces.last_mut() {
                        Some(Piece::Utt { persona: p, runs }) if *p == pname => runs.push(run),
                        _ => pieces.push(Piece::Utt { persona: pname, runs: vec![run] }),
                    }
                }
            }
        }

        // ---- render & stitch
        let sr = opt.sample_rate;
        let ms = |v: f32| (sr as f32 * v / 1000.0) as usize;
        let mut out: Vec<f32> = vec![0.0; ms(80.0)];
        let mut run_cues = Vec::new();
        let mut sent_cues = Vec::new();
        let mut prev: Option<(bool, f32)> = None; // (ended, pause_scale) of previous sentence
        let mut sentence_idx = 0u64;
        for piece in pieces {
            match piece {
                Piece::Pause(p) => {
                    out.extend(std::iter::repeat_n(0.0, ms(p)));
                    prev = None;
                }
                Piece::Breath => {
                    out.extend(std::iter::repeat_n(0.0, ms(60.0)));
                    out.extend(effects::breath(sr, 380.0, opt.seed + 991));
                    out.extend(std::iter::repeat_n(0.0, ms(80.0)));
                    prev = None;
                }
                Piece::Utt { persona, runs } => {
                    let persona = self.persona(&persona)?.clone();
                    for sent in split_sentences(runs) {
                        if let Some((ended, ps)) = prev {
                            let gap = if ended { opt.sentence_pause_ms * ps } else { 140.0 };
                            out.extend(std::iter::repeat_n(0.0, ms(gap)));
                        }
                        sentence_idx += 1;
                        let seed = opt.seed.wrapping_add(sentence_idx * 7919);
                        if self.verbose {
                            eprintln!("  [{}] {}", persona.name, sentence_text(&sent));
                        }
                        let sa = match persona.voice {
                            VoiceRef::Chatterbox { .. } => self.render_sentence_cb(&persona, &sent, sr, seed, opt),
                            _ => self.render_sentence_lite(&persona, &sent, sr, seed),
                        }
                        .with_context(|| format!("rendering \"{}\"", sentence_text(&sent)))?;
                        let off = out.len();
                        let t = |s: usize| (off + s) as f64 / sr as f64;
                        for (i, r) in sent.iter().enumerate() {
                            run_cues.push(Cue {
                                start: t(sa.bounds[i]),
                                end: t(sa.bounds[i + 1]),
                                text: r.text.clone(),
                                persona: persona.name.clone(),
                                mood: r.label.clone(),
                            });
                        }
                        sent_cues.push(Cue {
                            start: t(0),
                            end: t(*sa.bounds.last().unwrap()),
                            text: sentence_text(&sent),
                            persona: persona.name.clone(),
                            mood: sent.iter().map(|r| r.label.as_str()).collect::<Vec<_>>().join(" → "),
                        });
                        out.extend(&sa.audio);
                        prev = Some((sa.ended, sa.pause_scale));
                    }
                }
            }
        }
        out.extend(std::iter::repeat_n(0.0, ms(250.0)));
        if opt.normalize {
            effects::master(&mut out, sr, opt.target_db, -1.0);
        } else {
            effects::limiter(&mut out, sr, -0.3);
        }
        effects::fade(&mut out, sr, 5.0, 20.0);
        Ok(Rendered { samples: out, sample_rate: sr, runs: run_cues, sentences: sent_cues })
    }

    // ------------------------------------------------------------ expressive (Chatterbox)

    fn chatterbox(&mut self) -> Result<&mut Chatterbox> {
        if self.cb.is_none() {
            if self.verbose {
                eprintln!("loading Chatterbox (first use takes ~20 s)…");
            }
            self.cb = Some(Chatterbox::load(&chatterbox::default_dir(&self.models_dir), "high")?);
        }
        Ok(self.cb.as_mut().unwrap())
    }

    /// Reference voice (24 kHz) for an expressive persona.
    fn reference_audio(&mut self, persona: &Persona, clone: Option<&Path>) -> Result<Vec<f32>> {
        let key = match clone {
            Some(p) => format!("clone:{}", p.display()),
            None => persona.name.clone(),
        };
        if let Some(a) = self.cb_refs.get(&key) {
            return Ok(a.clone());
        }
        let dir = chatterbox::default_dir(&self.models_dir);
        let reference = match (&persona.voice, clone) {
            (_, Some(p)) => p.display().to_string(),
            (VoiceRef::Chatterbox { reference }, None) => reference.clone(),
            _ => bail!("persona '{}' is not an expressive persona", persona.name),
        };
        let audio = if reference == "default" {
            chatterbox::read_wav_24k(&dir.join("default_voice.wav"))?
        } else if let Some(src) = reference.strip_prefix("persona:") {
            let cache = dir.join("voices").join(format!("{src}.wav"));
            if cache.exists() {
                chatterbox::read_wav_24k(&cache)?
            } else {
                let sp = self.persona(src)?.clone();
                if matches!(sp.voice, VoiceRef::Chatterbox { .. }) {
                    bail!("reference persona '{src}' must be a lite persona");
                }
                if self.verbose {
                    eprintln!("building reference voice for '{}' from '{src}' (cached)…", persona.name);
                }
                let has_espeak = self.phon.is_some() || Phonemizer::new().is_ok();
                let (text, ipa) = match (sp.accent, has_espeak) {
                    (Accent::FrFr, true) => (REF_TEXT_FR, false),
                    (Accent::FrFr, false) => (REF_IPA_FR, true),
                    (Accent::EnUs, true) => (REF_TEXT_EN, false),
                    (Accent::EnUs, false) => (REF_IPA_EN, true),
                };
                let o = RenderOptions {
                    persona: src.into(),
                    sample_rate: chatterbox::SAMPLE_RATE,
                    ipa,
                    sentence_pause_ms: 300.0,
                    ..Default::default()
                };
                let r = self.render(text, &o)?;
                std::fs::create_dir_all(cache.parent().unwrap())?;
                crate::export::export(&cache, &r.samples, r.sample_rate, crate::export::Format::Wav, &Default::default())?;
                r.samples
            }
        } else {
            chatterbox::read_wav_24k(Path::new(&reference))?
        };
        let (s, e) = effects::trim_bounds(&audio, chatterbox::SAMPLE_RATE, 60.0);
        let mut a = audio[s..e].to_vec();
        a.truncate(chatterbox::SAMPLE_RATE as usize * 10);
        // consistent prompt level
        let r = crate::util::rms(&a).max(1e-4);
        let g = db_to_lin(-20.0) / r;
        a.iter_mut().for_each(|v| *v = (*v * g).clamp(-1.0, 1.0));
        self.cb_refs.insert(key, a.clone());
        Ok(a)
    }

    /// Voice conditioning for persona+mood. The persona's voice first performs an
    /// emotional line in that mood (cached on disk); that clip, further shaped by DSP,
    /// becomes the prompt, so the model carries the emotion into the target text.
    fn voice_cond(
        &mut self,
        persona: &Persona,
        mood: &Mood,
        dominant: Option<&(String, f32)>,
        opt: &RenderOptions,
    ) -> Result<VoiceCond> {
        let fr = persona.accent.is_french();
        let dom: Option<Mood> = dominant
            .filter(|(n, k)| *k >= 0.45 && n != "neutral")
            .and_then(|(n, _)| self.mood(n).ok().cloned());
        let prompt_text = dom.as_ref().map(|m| if fr { m.prompt_fr.clone() } else { m.prompt_en.clone() }).filter(|t| !t.is_empty());
        let strength = if prompt_text.is_some() { 0.5 } else { 1.0 };
        let prompt = prompt_style(mood, strength);
        let voice_id = match &opt.clone {
            Some(p) => {
                use std::hash::{Hash, Hasher};
                let mut h = std::collections::hash_map::DefaultHasher::new();
                p.hash(&mut h);
                format!("clone_{:x}", h.finish())
            }
            None => persona.name.clone(),
        };
        let key = format!(
            "{}|{}|{:.2}|{:.2}|{:.2}|{:.2}|{:.2}|{:.2}|{:.1}",
            voice_id,
            dom.as_ref().map(|m| m.name.as_str()).unwrap_or("-"),
            prompt.speed,
            prompt.pitch_st,
            prompt.pitch_range,
            prompt.whisper,
            prompt.breathiness,
            prompt.brightness_db,
            prompt.vibrato_cents + prompt.jitter_cents
        );
        if let Some(c) = self.cb_conds.get(&key) {
            return Ok(c.clone());
        }
        let reference = self.reference_audio(persona, opt.clone.as_deref())?;
        let source = match (&prompt_text, &dom) {
            (Some(text), Some(dm)) => {
                let dir = chatterbox::default_dir(&self.models_dir).join("voices");
                let cache = dir.join(format!("{voice_id}__{}.wav", dm.name));
                if cache.exists() {
                    chatterbox::read_wav_24k(&cache)?
                } else {
                    if self.verbose {
                        eprintln!("building '{}' emotional prompt for {voice_id} (cached)…", dm.name);
                    }
                    let base_key = format!("{voice_id}|base");
                    let base = match self.cb_conds.get(&base_key) {
                        Some(c) => c.clone(),
                        None => {
                            let c = self.chatterbox()?.encode_voice(&reference)?;
                            self.cb_conds.insert(base_key, c.clone());
                            c
                        }
                    };
                    let lang = if fr { "fr" } else { "en" };
                    let exag = (0.5 + dm.exaggeration * 1.4).clamp(0.3, 1.6);
                    let (w, ok) = self.cb_generate(text, lang, &base, exag, 11)?;
                    let (s, e) = effects::trim_bounds(&w, chatterbox::SAMPLE_RATE, 60.0);
                    let w = w[s..e.max(s)].to_vec();
                    if !ok || w.len() < chatterbox::SAMPLE_RATE as usize {
                        if self.verbose {
                            eprintln!("      emotional prompt rejected; using the neutral voice + shaping");
                        }
                        reference.clone()
                    } else {
                        std::fs::create_dir_all(&dir)?;
                        crate::export::export(&cache, &w, chatterbox::SAMPLE_RATE, crate::export::Format::Wav, &Default::default())?;
                        w
                    }
                }
            }
            _ => reference,
        };
        let shaped = if prompt.needs_psola()
            || (prompt.speed - 1.0).abs() > 0.02
            || prompt.whisper > 0.01
            || prompt.breathiness > 0.01
            || prompt.brightness_db.abs() > 0.1
        {
            let n = source.len();
            let (y, _) = fx_chain(&source, chatterbox::SAMPLE_RATE, &[0, n], &[prompt], 1.0, 17);
            y
        } else {
            source
        };
        let cond = self.chatterbox()?.encode_voice(&shaped)?;
        self.cb_conds.insert(key, cond.clone());
        Ok(cond)
    }

    /// Generate with quality checks: the model must stop by itself and the duration must
    /// be plausible for the text; otherwise retry with calmer decoding settings.
    fn cb_generate(&mut self, text: &str, lang: &str, cond: &VoiceCond, exag: f32, seed: u64) -> Result<(Vec<f32>, bool)> {
        let sr = chatterbox::SAMPLE_RATE;
        let chars = text.chars().filter(|c| c.is_alphanumeric()).count().max(1) as f32;
        let attempts = [(exag, 1.2f32), ((exag * 0.75).max(0.4), 1.3), (0.5, 1.4)];
        let mut best: Option<(f32, Vec<f32>)> = None;
        for (i, (e, rep)) in attempts.iter().enumerate() {
            let params = CbParams {
                exaggeration: *e,
                cfg_weight: 0.0,
                temperature: 0.0, // greedy: the most stable & clearest with this ONNX export
                repetition_penalty: *rep,
                seed,
                ..Default::default()
            };
            let mut w = self.chatterbox()?.synth(text, lang, cond, &params)?;
            let stopped = self.chatterbox()?.last_stopped;
            let raw = w.len();
            cut_hallucination(&mut w, sr, text);
            let secs = w.len() as f32 / sr as f32;
            // speech runs ~8-20 letters/s; outside 4-35 is a failed generation
            let rate = chars / secs.max(0.05);
            let ok = stopped && w.len() * 10 >= raw * 8 && (4.0..=35.0).contains(&rate);
            let score = (if stopped { 0.0 } else { 2.0 }) + (rate.ln() - 14f32.ln()).abs();
            if self.verbose && !ok {
                eprintln!("      retry {}: stopped={stopped} {:.1}s ({:.0} letters/s)", i + 1, secs, rate);
            }
            if ok {
                return Ok((w, true));
            }
            if best.as_ref().is_none_or(|(b, _)| score < *b) {
                best = Some((score, w));
            }
        }
        Ok((best.map(|b| b.1).unwrap_or_default(), false))
    }

    fn render_sentence_cb(
        &mut self,
        persona: &Persona,
        runs: &[Run],
        out_sr: u32,
        seed: u64,
        opt: &RenderOptions,
    ) -> Result<SentenceAudio> {
        let sr = chatterbox::SAMPLE_RATE;
        let lang = if persona.accent.is_french() { "fr" } else { "en" };
        let mut audio: Vec<f32> = Vec::new();
        let mut bounds = vec![0usize];
        for (i, r) in runs.iter().enumerate() {
            let last = i + 1 == runs.len();
            let mut text = match r.nonverbal.as_deref() {
                Some("laugh") => "Ha ha ha!".to_string(),
                Some("sigh") => "Haaah…".to_string(),
                _ if r.ipa => bail!("IPA input isn't supported by expressive personas; use a -lite persona"),
                _ => r.text.clone(),
            };
            if !last && !text.trim_end().ends_with(['.', '!', '?', ',', ';', ':', '…']) {
                text.push(','); // continuation intonation instead of a final fall
            }
            let exag = opt
                .emotion
                .unwrap_or(0.5 + r.mood.exaggeration + if r.explicit.emphasis { 0.15 } else { 0.0 })
                .clamp(0.25, 2.0);
            let cond = self.voice_cond(persona, &r.mood, r.dominant.as_ref(), opt)?;
            if self.verbose {
                eprintln!("    [{} · emotion {:.2}] {}", r.label, exag, text);
            }
            let (wav, _) = self.cb_generate(&text, lang, &cond, exag, seed.wrapping_add(i as u64))?;
            let (s, e) = effects::trim_bounds(&wav, sr, 30.0);
            let seg = &wav[s..e.max(s)];
            if !audio.is_empty() {
                let prev = runs[i - 1].text.trim_end();
                let gap_ms = if prev.ends_with(['.', '!', '?', '…']) {
                    260.0
                } else if prev.ends_with([',', ';', ':']) {
                    110.0
                } else {
                    40.0
                };
                audio.extend(std::iter::repeat_n(0.0, (sr as f32 * gap_ms / 1000.0) as usize));
            }
            audio.extend_from_slice(seg);
            bounds.push(audio.len());
        }
        if audio.is_empty() {
            return Ok(SentenceAudio { audio: vec![], bounds: vec![0; runs.len() + 1], ended: false, pause_scale: 1.0 });
        }
        // minimal post-processing: explicit pitch/rate, level, room, a touch of whisper
        let post: Vec<Mood> = runs.iter().map(post_style).collect();
        let (y, b) = fx_chain(&audio, sr, &bounds, &post, 1.0, seed);
        let ratio = out_sr as f64 / sr as f64;
        let y = effects::resample(&y, sr, out_sr);
        let ob: Vec<usize> = b.iter().map(|&v| ((v as f64 * ratio) as usize).min(y.len())).collect();
        let ended = runs.last().map(|r| ends_sentence(&r.text)).unwrap_or(false);
        Ok(SentenceAudio { audio: y, bounds: ob, ended, pause_scale: runs.last().unwrap().mood.pause_scale })
    }

    // ------------------------------------------------------------ lite (Kokoro / Piper)

    fn synth_lite(&mut self, persona: &Persona, phonemes: &str, ctl: &ModelControls) -> Result<SynthOut> {
        match &persona.voice {
            VoiceRef::Kokoro { voices } => {
                if self.kokoro.is_none() {
                    self.kokoro = Some(Kokoro::load(&self.models_dir.join("kokoro"))?);
                }
                self.kokoro.as_mut().unwrap().synth(phonemes, voices, ctl.speed, !persona.accent.is_french())
            }
            VoiceRef::Piper { model, speaker } => {
                if !self.piper.contains_key(model) {
                    let p = Piper::load(&self.models_dir.join("piper").join(format!("{model}.onnx")))?;
                    self.piper.insert(model.clone(), p);
                }
                self.piper.get_mut(model).unwrap().synth(phonemes, speaker.as_deref(), ctl)
            }
            VoiceRef::Chatterbox { .. } => unreachable!(),
        }
    }

    fn render_sentence_lite(&mut self, persona: &Persona, runs: &[Run], out_sr: u32, seed: u64) -> Result<SentenceAudio> {
        let voice = persona.accent.espeak_voice();
        let mut joined = String::new();
        let mut offsets = Vec::with_capacity(runs.len() + 1);
        for r in runs {
            let ph = if r.ipa { r.text.trim().to_string() } else { self.phonemizer()?.phonemize(&r.text, voice)? };
            if !joined.is_empty() && !ph.is_empty() {
                joined.push(' ');
            }
            offsets.push(joined.chars().count());
            joined.push_str(&ph);
        }
        let total_chars = joined.chars().count();
        offsets.push(total_chars);
        if total_chars == 0 {
            return Ok(SentenceAudio { audio: vec![], bounds: vec![0; runs.len() + 1], ended: false, pause_scale: 1.0 });
        }
        let weights: Vec<f32> = (0..runs.len()).map(|i| (offsets[i + 1] - offsets[i]).max(1) as f32).collect();
        let wsum: f32 = weights.iter().sum();
        let wavg = |f: &dyn Fn(&Mood) -> f32| runs.iter().zip(&weights).map(|(r, w)| f(&r.style) * w).sum::<f32>() / wsum;
        let speed_model = wavg(&|m| m.speed.max(0.1).ln()).exp();
        let ctl = ModelControls { speed: speed_model, expressiveness: wavg(&|m| m.expressiveness), rhythm: wavg(&|m| m.rhythm) };

        let syn = self.synth_lite(persona, &joined, &ctl)?;
        let sr = syn.sample_rate;
        let audio = syn.audio;
        let (ts, te) = effects::trim_bounds(&audio, sr, 40.0);
        if te <= ts {
            return Ok(SentenceAudio { audio: vec![], bounds: vec![0; runs.len() + 1], ended: false, pause_scale: 1.0 });
        }
        let mut bounds: Vec<usize> = vec![ts];
        for i in 1..runs.len() {
            let b = match &syn.char_starts {
                Some(cs) => cs[offsets[i].min(cs.len() - 1)],
                None => {
                    let guess = ts + ((te - ts) as f64 * offsets[i] as f64 / total_chars as f64) as usize;
                    let avg = (te - ts) / runs.len();
                    snap_to_valley(&audio, sr, guess, (sr as usize * 150 / 1000).min(avg / 3))
                }
            };
            bounds.push(b.clamp(*bounds.last().unwrap(), te));
        }
        bounds.push(te);
        let audio = audio[ts..te].to_vec();
        for b in bounds.iter_mut() {
            *b -= ts;
        }
        let styles: Vec<Mood> = runs.iter().map(|r| r.style.clone()).collect();
        let (y, b) = fx_chain(&audio, sr, &bounds, &styles, speed_model, seed);
        let ratio = out_sr as f64 / sr as f64;
        let y = effects::resample(&y, sr, out_sr);
        let ob: Vec<usize> = b.iter().map(|&v| ((v as f64 * ratio) as usize).min(y.len())).collect();
        let ended = runs.last().map(|r| ends_sentence(&r.text)).unwrap_or(false);
        Ok(SentenceAudio { audio: y, bounds: ob, ended, pause_scale: runs.last().unwrap().style.pause_scale })
    }
}

fn ends_sentence(t: &str) -> bool {
    t.trim_end_matches(['"', '»', '”', ')', '\'']).ends_with(['.', '!', '?', '…'])
}

/// How the voice prompt is re-shaped for a mood: prosody scaled by `k` (lighter when the
/// prompt is already an emotional performance), voice quality (whisper, breath) in full.
fn prompt_style(m: &Mood, k: f32) -> Mood {
    Mood {
        gain_db: 0.0,
        reverb: 0.0,
        speed: m.speed.powf(k),
        pitch_st: m.pitch_st * k,
        pitch_range: m.pitch_range.powf(k),
        pitch_slope_st: m.pitch_slope_st * k,
        jitter_cents: m.jitter_cents * k,
        vibrato_cents: m.vibrato_cents * k,
        brightness_db: m.brightness_db * k,
        tremolo_depth: m.tremolo_depth * 0.5,
        ..m.clone()
    }
}

/// Post-processing for expressive runs: only what the model can't do itself.
fn post_style(r: &Run) -> Mood {
    let m = &r.mood;
    let e = &r.explicit;
    Mood {
        name: m.name.clone(),
        speed: e.rate,
        pitch_st: e.pitch_st,
        gain_db: e.gain_db + 0.35 * m.gain_db + if e.emphasis { 2.0 } else { 0.0 },
        brightness_db: 0.25 * m.brightness_db,
        whisper: 0.35 * m.whisper,
        reverb: m.reverb,
        tremolo_hz: m.tremolo_hz,
        tremolo_depth: 0.5 * m.tremolo_depth,
        pause_scale: m.pause_scale,
        ..Mood::default()
    }
}

/// Cut trailing hallucinations: a long silence after speech, then more "speech".
fn cut_hallucination(wav: &mut Vec<f32>, sr: u32, text: &str) {
    let frame = (sr / 50) as usize; // 20 ms
    if wav.len() < frame * 10 {
        return;
    }
    let rms: Vec<f32> = wav.chunks(frame).map(crate::util::rms).collect();
    let peak = rms.iter().cloned().fold(0.0, f32::max).max(1e-6);
    let silent: Vec<bool> = rms.iter().map(|r| *r < peak * db_to_lin(-38.0)).collect();
    let min_speech = 25; // 0.5 s
    let mut spoken = 0;
    let mut run = 0;
    for (i, s) in silent.iter().enumerate() {
        if *s {
            run += 1;
            if spoken >= min_speech && run >= 45 {
                // ≥0.9 s of silence: everything after is unreliable
                wav.truncate((i + 1 - run + 10) * frame);
                return;
            }
        } else {
            run = 0;
            spoken += 1;
        }
    }
    // overly long output for the text length
    let expected = (text.chars().count() as f32 / 11.0 + 1.0) * 2.2;
    let max = (expected * sr as f32) as usize;
    if wav.len() > max {
        wav.truncate(max);
        let n = wav.len();
        let f = (sr as usize / 20).min(n);
        for i in 0..f {
            wav[n - f + i] *= 1.0 - i as f32 / f as f32;
        }
    }
}

/// Per-run DSP: smoothed control curves -> PSOLA (pitch/intonation/tempo, only if
/// needed) -> whisper/breath -> tilt -> gain/tremolo -> room.
/// `bounds` are run starts in samples (len = styles+1). Returns audio and mapped bounds.
fn fx_chain(audio: &[f32], sr: u32, bounds: &[usize], styles: &[Mood], speed_model: f32, seed: u64) -> (Vec<f32>, Vec<usize>) {
    let n = audio.len();
    if n == 0 {
        return (vec![], bounds.to_vec());
    }
    let build = |f: &dyn Fn(&Mood, f32) -> f32| -> Vec<f32> {
        let mut v = vec![0.0f32; n];
        for (i, s) in styles.iter().enumerate() {
            let (a, b) = (bounds[i].min(n), bounds[i + 1].min(n));
            let len = (b.saturating_sub(a)).max(1) as f32;
            for (j, x) in v[a..b].iter_mut().enumerate() {
                *x = f(s, j as f32 / len - 0.5);
            }
        }
        smooth(&v, (sr as usize * 35) / 1000)
    };
    let pitch_c = build(&|m, u| m.pitch_st + m.pitch_slope_st * u);
    let range_c = build(&|m, _| m.pitch_range);
    let stretch_c = build(&|m, _| speed_model / m.speed.max(0.1));
    let jitter_c = build(&|m, _| m.jitter_cents);
    let vib_c = build(&|m, _| m.vibrato_cents);
    let vib_hz = build(&|m, _| m.vibrato_hz);
    let gain_c = build(&|m, _| m.gain_db);
    let bright_c = build(&|m, _| m.brightness_db);
    let breath_c = build(&|m, _| m.breathiness);
    let whisper_c = build(&|m, _| m.whisper);
    let trem_c = build(&|m, _| m.tremolo_depth);
    let trem_hz = build(&|m, _| m.tremolo_hz);
    let reverb_c = build(&|m, _| m.reverb);

    let needs = styles.iter().any(|m| m.needs_psola()) || stretch_c.iter().any(|s| (s - 1.0).abs() > 0.02);
    let (mut y, anchors) = if needs {
        let f0 = yin(audio, sr);
        let mu = f0.log_mean().unwrap_or(150f32.ln());
        let marks = pitch_marks(audio, &f0, sr);
        let mut rng = Rng::new(seed);
        let step = (sr / 100) as usize;
        let mut jit = vec![0.0f32; n / step + 2];
        let mut s = 0.0f32;
        for v in jit.iter_mut() {
            s = 0.6 * s + 0.4 * rng.gauss();
            *v = s;
        }
        let mut phase = vec![0.0f32; n];
        let mut ph = 0.0f32;
        for i in 0..n {
            ph += 2.0 * std::f32::consts::PI * vib_hz[i] / sr as f32;
            phase[i] = ph;
        }
        let pitch_fn = |pos: usize, fmark: f32| -> f32 {
            let p = pos.min(n - 1);
            let f = {
                let v = f0.at(p);
                if v > 0.0 { v } else { fmark }
            };
            let st = pitch_c[p] + vib_c[p] / 100.0 * phase[p].sin() + jitter_c[p] / 100.0 * jit[p / step];
            let target = (mu + range_c[p] * (f.ln() - mu)).exp() * 2f32.powf(st / 12.0);
            target / f
        };
        let stretch_fn = |pos: usize| stretch_c[pos.min(n - 1)];
        psola(audio, &marks, sr, pitch_fn, stretch_fn)
    } else {
        (audio.to_vec(), vec![(0.0, 0.0), (n as f64, n as f64)])
    };
    let m = y.len();
    let in_of: Vec<usize> = if needs {
        (0..m).map(|i| (map_time(&anchors, i as f64, false) as usize).min(n - 1)).collect()
    } else {
        (0..m).map(|i| i.min(n - 1)).collect()
    };
    let at = |c: &Vec<f32>, i: usize| c[in_of[i]];
    let max = |c: &Vec<f32>| c.iter().cloned().fold(0.0f32, f32::max);
    if max(&whisper_c) > 0.01 || max(&breath_c) > 0.01 {
        let wn = effects::lpc_noise(&y, sr, seed ^ 0xBEEF);
        for i in 0..m {
            let (w, b) = (at(&whisper_c, i), at(&breath_c, i));
            y[i] = y[i] * (1.0 - w) * (1.0 - 0.3 * b) + wn[i] * (w + 0.55 * b);
        }
    }
    if bright_c.iter().any(|v| v.abs() > 0.05) {
        effects::tilt(&mut y, sr, &|i| at(&bright_c, i));
    }
    let mut tph = 0.0f32;
    for i in 0..m {
        tph += 2.0 * std::f32::consts::PI * at(&trem_hz, i) / sr as f32;
        let trem = 1.0 - at(&trem_c, i) * (0.5 + 0.5 * tph.sin());
        y[i] *= db_to_lin(at(&gain_c, i)) * trem;
    }
    if max(&reverb_c) > 0.01 {
        let wet = effects::reverb(&y, sr);
        let tail = (sr as usize * 350 / 1000).min(wet.len() - m);
        let last_wet = at(&reverb_c, m - 1);
        let mut z = y.clone();
        z.extend(std::iter::repeat_n(0.0, tail));
        for i in 0..z.len() {
            let k = if i < m { at(&reverb_c, i) } else { last_wet * (1.0 - (i - m) as f32 / tail.max(1) as f32) };
            z[i] += wet[i] * k * 1.4;
        }
        y = z;
    }
    let mut ob: Vec<usize> = bounds
        .iter()
        .map(|&b| {
            let o = if needs { map_time(&anchors, b as f64, true) } else { b as f64 };
            (o as usize).min(y.len())
        })
        .collect();
    *ob.last_mut().unwrap() = m;
    (y, ob)
}

fn sentence_text(runs: &[Run]) -> String {
    runs.iter().map(|r| r.text.as_str()).collect::<Vec<_>>().join(" ")
}

/// Box-filter twice (~triangular) for smooth parameter transitions.
fn smooth(v: &[f32], half: usize) -> Vec<f32> {
    if half == 0 || v.len() < 3 {
        return v.to_vec();
    }
    let pass = |x: &[f32]| -> Vec<f32> {
        let n = x.len();
        let mut pre = vec![0.0f64; n + 1];
        for i in 0..n {
            pre[i + 1] = pre[i] + x[i] as f64;
        }
        (0..n)
            .map(|i| {
                let a = i.saturating_sub(half);
                let b = (i + half + 1).min(n);
                ((pre[b] - pre[a]) / (b - a) as f64) as f32
            })
            .collect()
    };
    pass(&pass(v))
}

fn snap_to_valley(x: &[f32], sr: u32, guess: usize, radius: usize) -> usize {
    let win = (sr / 100) as usize;
    let step = (sr / 400) as usize;
    let lo = guess.saturating_sub(radius);
    let hi = (guess + radius).min(x.len().saturating_sub(win));
    if hi <= lo {
        return guess.min(x.len());
    }
    let mut best = (f32::MAX, guess);
    let mut p = lo;
    while p <= hi {
        let e = crate::util::rms(&x[p..p + win]);
        let d = (p as f32 - guess as f32).abs() / radius.max(1) as f32;
        let score = e * (1.0 + 0.5 * d);
        if score < best.0 {
            best = (score, p + win / 2);
        }
        p += step;
    }
    best.1
}

const ABBREV: &[&str] = &[
    "mr", "mrs", "ms", "dr", "st", "vs", "etc", "jr", "sr", "prof", "inc", "e.g", "i.e", "m", "mme", "mlle", "no", "p",
    "av", "bd", "cf",
];

/// Split a persona's runs into sentences, keeping style runs that cross boundaries.
fn split_sentences(runs: Vec<Run>) -> Vec<Vec<Run>> {
    let mut out: Vec<Vec<Run>> = Vec::new();
    let mut cur: Vec<Run> = Vec::new();
    let mut cur_len = 0usize;
    for r in runs {
        let chars: Vec<char> = r.text.chars().collect();
        let mut start = 0;
        let mut i = 0;
        while i < chars.len() {
            let c = chars[i];
            let at_end = i + 1 == chars.len();
            let next_space = at_end || chars[i + 1].is_whitespace() || "\"'»”)".contains(chars[i + 1]);
            let mut split = false;
            if ".!?…".contains(c) && next_space {
                let word: String = chars[start..i]
                    .iter()
                    .rev()
                    .take_while(|c| !c.is_whitespace())
                    .collect::<String>()
                    .chars()
                    .rev()
                    .collect::<String>()
                    .to_ascii_lowercase();
                split = !(c == '.' && ABBREV.contains(&word.trim_start_matches(['(', '"', '«']).as_ref()));
            } else if ",;:".contains(c) && next_space && cur_len + (i - start) > 240 {
                split = true;
            }
            if split {
                let mut j = i + 1;
                while j < chars.len() && "\"'»”)".contains(chars[j]) {
                    j += 1;
                }
                let piece: String = chars[start..j].iter().collect::<String>().trim().to_string();
                if !piece.is_empty() {
                    cur.push(Run { text: piece, ..r.clone() });
                }
                if !cur.is_empty() {
                    out.push(std::mem::take(&mut cur));
                }
                cur_len = 0;
                start = j;
                i = j;
                continue;
            }
            i += 1;
        }
        let rest: String = chars[start..].iter().collect::<String>().trim().to_string();
        if !rest.is_empty() && rest.chars().any(|c| c.is_alphanumeric()) {
            cur_len += rest.len();
            cur.push(Run { text: rest, ..r });
        } else if !rest.is_empty() {
            if let Some(last) = cur.last_mut() {
                last.text.push_str(&rest);
            }
        }
    }
    if !cur.is_empty() {
        out.push(cur);
    }
    out
}

/// Parse a CLI mood spec like "happy", "happy:0.6", "happy 60%+whisper:0.3".
pub fn parse_mood_arg(s: &str) -> Result<Vec<(String, f32)>> {
    let mut v = Vec::new();
    for part in s.split('+') {
        let p = part.trim().replace([':', '='], " ");
        let mut it = p.split_whitespace();
        let Some(name) = it.next() else { continue };
        let k = match it.next() {
            Some(x) if x.ends_with('%') => x.trim_end_matches('%').parse::<f32>().map(|v| v / 100.0)?,
            Some(x) => x.parse::<f32>()?,
            None => 1.0,
        };
        if !(0.0..=2.0).contains(&k) {
            bail!("intensity must be 0..1 (got {k})");
        }
        v.push((name.to_ascii_lowercase(), k));
    }
    Ok(v)
}

#[cfg(test)]
mod tests {
    use super::*;
    fn run(t: &str) -> Run {
        Run {
            text: t.into(),
            ipa: false,
            style: Mood::default(),
            mood: Mood::default(),
            explicit: Explicit { rate: 1.0, pitch_st: 0.0, gain_db: 0.0, emphasis: false },
            label: "n".into(),
            nonverbal: None,
            dominant: None,
        }
    }
    #[test]
    fn sentences_split_across_runs() {
        let s = split_sentences(vec![run("Hello there. I was so"), run("happy until"), run("you left. Bye!")]);
        assert_eq!(s.len(), 3);
        assert_eq!(s[1].len(), 3);
        assert_eq!(s[1][0].text, "I was so");
        assert_eq!(s[2][0].text, "Bye!");
    }
    #[test]
    fn abbreviations() {
        let s = split_sentences(vec![run("Dr. Smith met M. Dupont. Then left.")]);
        assert_eq!(s.len(), 2);
    }
    #[test]
    fn mood_arg() {
        let v = parse_mood_arg("happy:60%+whisper 0.3").unwrap();
        assert_eq!(v, vec![("happy".into(), 0.6), ("whisper".into(), 0.3)]);
    }
    #[test]
    fn hallucination_cut() {
        let sr = 24000;
        let mut w: Vec<f32> = (0..sr).map(|i| (i as f32 * 0.05).sin() * 0.3).collect();
        w.extend(vec![0.0; sr * 2]);
        w.extend((0..sr).map(|i| (i as f32 * 0.07).sin() * 0.3));
        cut_hallucination(&mut w, sr as u32, "short text here");
        assert!(w.len() < sr * 2, "len {}", w.len());
    }
}
